adj=collections.defaultdict(list)
for u,v,t in events:
    adj[u].append((v,t)); adj[v].append((u,t))
for k in adj: adj[k].sort(key=lambda x:x[1])

def reach(src,dst,tmin,tmax_start,gap,tend):
    best={}
    prev={}
    h=[]
    for c,t in adj[src]:
        if tmin<=t<=tmax_start and t<=tend:
            heapq.heappush(h,(t,c))
            if c not in best or best[c]>t: best[c]=t; prev[c]=(src,t)
    while h:
        t,n=heapq.heappop(h)
        if best.get(n,1e18)<t: continue
        if n==dst: break
        for c,t2 in adj[n]:
            if t<t2<=t+gap and t2<=tend and (c not in best or best[c]>t2):
                best[c]=t2; prev[c]=(n,t2); heapq.heappush(h,(t2,c))
    if dst not in best: return None,None
    path=[]; cur=dst
    while cur!=src:
        p,t=prev[cur]; path.append((p,cur,t)); cur=p
    return best[dst], path[::-1]

