def earliest_route_start(src,dst,gap,tend):
    # for each possible first-hop time, does dst become reachable?
    starts=sorted(t for c,t in adj[src])
    out=[]
    for st in starts:
        best={}; 
        for c,t in adj[src]:
            if t==st: best[c]=t
        changed=True
        while changed:
            changed=False
            for n in list(best):
                t=best[n]
                for c,t2 in adj[n]:
                    if t<t2<=t+gap and t2<=tend and (c not in best or best[c]>t2):
                        best[c]=t2; changed=True
        out.append((st, best.get(dst)))
    return out
